INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yume-neko-ds-japan', 'NDS', 'Yume Neko DS (Japan)', '2007', 'Simulation', 'Takara Tomy', '1', 'Pet Simulation', 'Simulation.', 'Care for and play with virtual kittens.', 'Cute cat-raising simulation for Japan.', 'Yume Neko DS (Japan) lets you adopt and nurture various breeds of kittens. Use the touch screen to pet them and the mic to call their names.');
