INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoo-tycoon-2-ds-usa', 'NDS', 'Zoo Tycoon 2 DS (USA)', '2008', 'Simulation', 'Blue Fang Games', '1', 'Zoo Management', 'Simulation.', 'Build and manage a successful zoo.', 'North American release of Zoo Tycoon 2.', 'Zoo Tycoon 2 DS (USA) features two modes of play: a structured campaign and a creative "Freeform" sandbox mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoo-tycoon-ds---doubutsuen-o-tsukurou!-japan', 'NDS', 'Zoo Tycoon DS - Doubutsuen o Tsukurou! (Japan)', '2005', 'Simulation', 'Altron', '1', 'Zoo Management', 'Simulation.', 'Build the zoo of your dreams.', 'Japanese version of the original Tycoon.', 'Zoo Tycoon DS (Japan) lets you build habitats from scratch. Manage staff and balance your budget in this handheld classic.');
