INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zubo-europe-enfrdeesitnlsv', 'NDS', 'Zubo (Europe) (En,Fr,De,Es,It,Nl,Sv)', '2009', 'Adventure', 'Etranges Libellules', '1', 'Music Adventure', 'Rhythm RPG.', 'Save the world of Zubo with music.', 'Innovative rhythm-based RPG for Europe.', 'Zubo (Europe) features over 50 "Zubos" to collect. Master the beat-based combat system to defeat the evil clones of Big Head.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zubo-usa-enfres', 'NDS', 'Zubo (USA) (En,Fr,Es)', '2009', 'Adventure', 'Etranges Libellules', '1', 'Music Adventure', 'Rhythm RPG.', 'Save the world of Zubo with music.', 'North American release of Zubo.', 'Zubo (USA) is known for its quirky humor and unique stylus-based rhythmic battles. Explore the world and build your Zubo army.');
