INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zunou-nouryoku-koujou-machine---touch-de-zunoo-ds-japan', 'NDS', 'Zunou Nouryoku Koujou Machine - Touch de Zunoo DS (Japan)', '2007', 'Educational', 'Nintendo', '1', 'Brain Training', 'Brain Training.', 'Test your mental age with the machine.', 'Rapid-fire cognitive trainer for Japan.', 'Touch de Zunoo DS (Japan) provides a full "brain diagnostic". Improve your reaction time and memory through daily touch-screen tests.');